                'title' => $session->title,
                'responses' => $data,
                'images' => $images,
                'sceneKey' => $session->scene_key,
                'createdAt' => $session->created_at ? $session->created_at->getTimestampMs() : 0,
                'updatedAt' => $session->updated_at ? $session->updated_at->getTimestampMs() : 0,
            ];
        }

