                $size = filesize(public_path($path));
                if (empty($size)) {
                    return Base::retError('消息发送保存失败');
                }
                $type = $markdown ? 'md' : 'htm';
                $desc = $text;
                if ($markdown) {
                    $desc = preg_replace("/:::\s*reasoning[\s\S]*?:::/", "", $desc);
