            $progress = 0;
            $zip->registerProgressCallback(0.05, function ($ratio) use ($userid, $fileUrl, $fileName, &$progress) {
                $progress = round($ratio * 100);
                File::pushMsgSimple('compress', [
                    'name' => $fileName,
                    'url' => $fileUrl,
                    'progress' => $progress
                ], $userid);
            });
            //
            foreach ($files as $file) {
                File::addFileTreeToZip($zip, $file);
            }
            $zip->close();
            //
            if ($progress < 100) {
                File::pushMsgSimple('compress', [
                    'name' => $fileName,
                    'url' => $fileUrl,
                    'progress' => 100
